CompletableFuture<String> chain = CompletableFuture
    .supplyAsync(() -> fetchRawData())
    .thenApply(raw -> processData(raw))
    .thenApply(processed -> "WYNIK -> " + processed)
    .exceptionally(ex -> "BLAD: " + ex.getCause().getMessage());
String result = chain.get(5, TimeUnit.SECONDS);

// thenApply + funkcja zwracajaca CompletableFuture -> ZAGNIEZDZONY typ
CompletableFuture<CompletableFuture<Integer>> nested = base.thenApply(Lesson::asyncDouble);
nested.get().get(); // trzeba 'odpakowac' DWA razy

// thenCompose + ta sama funkcja -> SPLASZCZONY typ
CompletableFuture<Integer> flattened = base.thenCompose(Lesson::asyncDouble);
flattened.get(); // wystarczy 1x get()

CompletableFuture<Double> priceInUsd = CompletableFuture.supplyAsync(() -> pobierzCene());
CompletableFuture<Double> usdToPlnRate = CompletableFuture.supplyAsync(() -> pobierzKurs());
CompletableFuture<String> combined = priceInUsd.thenCombine(usdToPlnRate,
    (price, rate) -> "Cena w PLN: " + (price * rate));
// oba obliczenia licza sie ROWNOLEGLE, thenCombine czeka na OBA i laczy wyniki

exercises.solution:
CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> { throw new RuntimeException("blad"); })
    .exceptionally(ex -> "wartosc domyslna");
System.out.println(cf.get());

CompletableFuture<Integer> base = CompletableFuture.supplyAsync(() -> 10);
CompletableFuture<CompletableFuture<Integer>> zagniezdzony = base.thenApply(n -> CompletableFuture.supplyAsync(() -> n*2));
System.out.println(zagniezdzony.get().get());
CompletableFuture<Integer> splaszczony = base.thenCompose(n -> CompletableFuture.supplyAsync(() -> n*2));
System.out.println(splaszczony.get());

CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> { sleepQuiet(50); return 10; });
CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> { sleepQuiet(30); return 20; });
CompletableFuture<Integer> wynik = a.thenCombine(b, Integer::sum);
System.out.println(wynik.get()); // 30

CompletableFuture<String> cf = CompletableFuture.completedFuture("juz gotowe");
System.out.println(cf.isDone()); // true
System.out.println(cf.get()); // juz gotowe (natychmiastowo)

CompletableFuture<Integer> cf = CompletableFuture.supplyAsync(() -> { throw new RuntimeException("blad"); });
try { cf.get(); } catch (ExecutionException e) { System.out.println("get(): "+e.getCause()); } catch (InterruptedException e) {}
CompletableFuture<Integer> cf2 = CompletableFuture.supplyAsync(() -> { throw new RuntimeException("blad2"); });
try { cf2.join(); } catch (CompletionException e) { System.out.println("join(): "+e.getCause()); }

static CompletableFuture<Integer> asyncDouble(int value) { return CompletableFuture.supplyAsync(() -> value*2); }
CompletableFuture<Integer> wynik = CompletableFuture.supplyAsync(() -> 5).thenCompose(Lesson::asyncDouble);
System.out.println(wynik.get()); // 10

CompletableFuture<Void> cf = CompletableFuture.supplyAsync(() -> { System.out.println("supply: "+Thread.currentThread().getName()); return 1; })
    .thenApply(n -> { System.out.println("apply: "+Thread.currentThread().getName()); return n+1; })
    .thenAccept(n -> System.out.println("accept: "+Thread.currentThread().getName()+" wynik="+n));
cf.get();

for (String dane : new String[]{"dobre", "zle"}) {
    CompletableFuture<String> lancuch = CompletableFuture.supplyAsync(() -> dane)
        .thenApply(d -> { if (d.equals("zle")) throw new IllegalArgumentException("nieprawidlowe dane"); return d.toUpperCase(); })
        .thenApply(d -> "zapisano: "+d)
        .exceptionally(ex -> "blad zapisu: "+ex.getCause().getMessage());
    System.out.println(lancuch.get());
}

ExecutorService wlasnaP pula = Executors.newFixedThreadPool(2);
CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> 5)
    .thenApplyAsync(n -> { System.out.println(Thread.currentThread().getName()); return n*2; }, wlasnaPula);
System.out.println(cf.get());
wlasnaPula.shutdown(); wlasnaPula.awaitTermination(5, TimeUnit.SECONDS);

long t0 = System.nanoTime();
CompletableFuture<Double> cena = CompletableFuture.supplyAsync(() -> { sleepQuiet(200); return 100.0; });
CompletableFuture<Double> kurs = CompletableFuture.supplyAsync(() -> { sleepQuiet(150); return 4.0; });
CompletableFuture<Double> wynik = cena.thenCombine(kurs, (c,k) -> c*k);
System.out.println(wynik.get()+" po "+(System.nanoTime()-t0)/1_000_000+"ms (bliskie 200ms, nie 350ms)");

CompletableFuture<Integer> cf1 = CompletableFuture.supplyAsync(() -> 1);
CompletableFuture<Integer> cf2 = CompletableFuture.supplyAsync(() -> 2);
CompletableFuture<Integer> cf3 = CompletableFuture.supplyAsync(() -> 3);
CompletableFuture.allOf(cf1, cf2, cf3).get();
System.out.println(cf1.get()+cf2.get()+cf3.get()); // 6

CompletableFuture<String> szybkie = CompletableFuture.supplyAsync(() -> { sleepQuiet(50); return "szybkie"; });
CompletableFuture<String> wolne = CompletableFuture.supplyAsync(() -> { sleepQuiet(500); return "wolne"; });
Object wynik = CompletableFuture.anyOf(szybkie, wolne).get();
System.out.println(wynik); // szybkie

BiFunction<Integer, Throwable, String> handler = (wynik, blad) -> blad != null ? "blad: "+blad.getMessage() : "sukces: "+wynik;
CompletableFuture<String> sukces = CompletableFuture.supplyAsync(() -> 42).handle(handler);
System.out.println(sukces.get());
CompletableFuture<String> porazka = CompletableFuture.<Integer>supplyAsync(() -> { throw new RuntimeException("cos poszlo nie tak"); }).handle(handler);
System.out.println(porazka.get());

CompletableFuture<Integer> cf = CompletableFuture.supplyAsync(() -> 42)
    .whenComplete((wynik, blad) -> { if (blad != null) System.out.println("log: blad "+blad); else System.out.println("log: sukces "+wynik); });
System.out.println(cf.get()); // 42 - whenComplete NIE zmienil wyniku

AtomicInteger proby = new AtomicInteger(0);
Supplier<CompletableFuture<String>> zadanie = () -> CompletableFuture.supplyAsync(() -> { int p = proby.incrementAndGet(); if (p < 2) throw new RuntimeException("proba "+p+" nieudana"); return "sukces przy probie "+p; });
CompletableFuture<String> wynik = zadanie.get().handle((w, e) -> e != null ? zadanie.get() : CompletableFuture.completedFuture(w)).thenCompose(cf -> cf);
System.out.println(wynik.get());

CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> 1);
CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> 2);
CompletableFuture<Integer> c = CompletableFuture.supplyAsync(() -> 3);
CompletableFuture<List<Integer>> wszystkie = CompletableFuture.allOf(a,b,c).thenApply(v -> List.of(a.join(), b.join(), c.join()));
System.out.println(wszystkie.get());

static <T> T withTimeout(CompletableFuture<T> cf, long timeoutMs, T fallback) { return cf.completeOnTimeout(fallback, timeoutMs, TimeUnit.MILLISECONDS).join(); }
CompletableFuture<String> szybkie = CompletableFuture.supplyAsync(() -> { sleepQuiet(50); return "szybki wynik"; });
System.out.println(withTimeout(szybkie, 500, "domyslny"));
CompletableFuture<String> wolne = CompletableFuture.supplyAsync(() -> { sleepQuiet(1000); return "wolny wynik"; });
System.out.println(withTimeout(wolne, 200, "domyslny"));

CompletableFuture<Integer> s1 = CompletableFuture.supplyAsync(() -> { sleepQuiet(50); return 10; }).exceptionally(ex -> 0);
CompletableFuture<Integer> s2 = CompletableFuture.supplyAsync(() -> { sleepQuiet(100); throw new RuntimeException("serwis 2 padl"); }).exceptionally(ex -> 0);
CompletableFuture<Integer> s3 = CompletableFuture.supplyAsync(() -> { sleepQuiet(150); return 30; }).exceptionally(ex -> 0);
CompletableFuture<Integer> s4 = CompletableFuture.supplyAsync(() -> { sleepQuiet(200); return 40; }).exceptionally(ex -> 0);
CompletableFuture<Integer> suma = CompletableFuture.allOf(s1,s2,s3,s4).thenApply(v -> s1.join()+s2.join()+s3.join()+s4.join());
System.out.println(suma.get()); // 80 (serwis 2 dal 0 zamiast bledu)

record Order(int id, int quantity, double unitPrice) {}
CompletableFuture<Double> pipeline = CompletableFuture.supplyAsync(() -> new Order(1, 3, 10.0))
    .thenApply(o -> { if (o.quantity() <= 0) throw new IllegalArgumentException("zla ilosc"); return o; })
    .thenCompose(o -> CompletableFuture.supplyAsync(() -> { sleepQuiet(30); return o; })) // symulacja sprawdzenia magazynu
    .thenCombine(CompletableFuture.supplyAsync(() -> { sleepQuiet(20); return 0.1; }), (o, rabat) -> o.quantity()*o.unitPrice()*(1-rabat))
    .exceptionally(ex -> -1.0);
System.out.println(pipeline.get());

CompletableFuture<String> wolne = CompletableFuture.supplyAsync(() -> { sleepQuiet(1000); return "wolny wynik"; })
    .orTimeout(200, TimeUnit.MILLISECONDS)
    .exceptionally(ex -> "timeout: "+ex.getClass().getSimpleName());
System.out.println(wolne.get());

List<CompletableFuture<String>> zapytania = new ArrayList<>();
int[] czasy = {50, 800, 100, 700, 200, 600};
for (int i=0;i<6;i++) { int id=i; long czas=czasy[i]; zapytania.add(CompletableFuture.supplyAsync(() -> { sleepQuiet(czas); return "wynik-"+id; }).orTimeout(300, TimeUnit.MILLISECONDS).exceptionally(ex -> "fallback-"+id)); }
CompletableFuture.allOf(zapytania.toArray(new CompletableFuture[0])).join();
List<String> wyniki = zapytania.stream().map(CompletableFuture::join).toList();
System.out.println(wyniki);

static CompletableFuture<Boolean> sprawdzHaslo(String haslo) { return CompletableFuture.supplyAsync(() -> { if (haslo.equals("zle")) throw new SecurityException("zle haslo"); return true; }); }
static CompletableFuture<List<String>> pobierzUprawnienia(boolean ok) { return CompletableFuture.supplyAsync(() -> List.of("READ", "WRITE")); }
static CompletableFuture<String> zbudujSesje(List<String> uprawnienia) { return CompletableFuture.supplyAsync(() -> "sesja-"+uprawnienia.size()); }
CompletableFuture<String> wynik = sprawdzHaslo("dobre").thenCompose(_Lesson32_CompletableFuture::pobierzUprawnienia).thenCompose(_Lesson32_CompletableFuture::zbudujSesje).exceptionally(ex -> "blad autoryzacji: "+ex.getCause().getMessage());
System.out.println(wynik.get());

CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> 10);
CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> 20);
CompletableFuture<Integer> c = CompletableFuture.supplyAsync(() -> 30);
CompletableFuture<Integer> d = a.thenCombine(b, Integer::sum).thenCombine(c, Integer::sum);
System.out.println(d.get()); // 60

long t0 = System.nanoTime();
for (int i=0;i<5;i++) sleepQuiet(100);
long sekwencyjnie = (System.nanoTime()-t0)/1_000_000;
t0 = System.nanoTime();
List<CompletableFuture<Void>> zadania = new ArrayList<>();
for (int i=0;i<5;i++) zadania.add(CompletableFuture.runAsync(() -> sleepQuiet(100)));
CompletableFuture.allOf(zadania.toArray(new CompletableFuture[0])).join();
long rownolegle = (System.nanoTime()-t0)/1_000_000;
System.out.println("sekwencyjnie: "+sekwencyjnie+"ms rownolegle: "+rownolegle+"ms");

ConcurrentHashMap<String, CompletableFuture<String>> cache = new ConcurrentHashMap<>();
AtomicInteger liczbaObliczen = new AtomicInteger(0);
Function<String, CompletableFuture<String>> pobierz = klucz -> cache.computeIfAbsent(klucz, k -> CompletableFuture.supplyAsync(() -> { liczbaObliczen.incrementAndGet(); sleepQuiet(50); return "wynik-dla-"+k; }));
CompletableFuture<String> a = pobierz.apply("klucz1");
CompletableFuture<String> b = pobierz.apply("klucz1");
System.out.println(a == b); // true - ten sam CompletableFuture
System.out.println(a.get()+" "+b.get());
System.out.println("liczba faktycznych obliczen: "+liczbaObliczen.get()); // 1

CompletableFuture<Boolean> dostepnosc = CompletableFuture.supplyAsync(() -> { sleepQuiet(50); return true; }).orTimeout(500, TimeUnit.MILLISECONDS).exceptionally(ex -> false);
CompletableFuture<Double> rabat = CompletableFuture.supplyAsync(() -> { sleepQuiet(30); return 0.1; }).orTimeout(500, TimeUnit.MILLISECONDS).exceptionally(ex -> 0.0);
CompletableFuture<Double> dostawa = CompletableFuture.supplyAsync(() -> { sleepQuiet(40); return 15.0; }).orTimeout(500, TimeUnit.MILLISECONDS).exceptionally(ex -> 20.0);
CompletableFuture<double[]> etap1 = dostepnosc.thenCombine(rabat, (d, r) -> new double[]{d?1:0, r});
CompletableFuture<Double> finalna = etap1.thenCombine(dostawa, (arr, dost) -> arr[0]==1 ? (100.0*(1-arr[1])+dost) : -1.0)
    .whenComplete((wynik, blad) -> System.out.println(blad != null ? "blad zamowienia" : "zamowienie przetworzone, cena="+wynik));
System.out.println(finalna.get());

Random rnd = new Random(42);
int sukcesy = 0, bledy = 0;
for (int i=0;i<20;i++) {
    boolean symulujBlad = rnd.nextDouble() < 0.2;
    CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> { if (symulujBlad) throw new RuntimeException("celowy blad"); return "dane"; })
        .thenApply(d -> d.toUpperCase())
        .exceptionally(ex -> "BLAD: "+ex.getCause().getMessage());
    String wynik = cf.get();
    if (wynik.startsWith("BLAD")) bledy++; else sukcesy++;
}
System.out.println("sukcesy="+sukcesy+" bledy="+bledy);
